// ⤢ PEGAR: ESCALADO — YA NO ES UN SNIPPET
// =======================================
// Este snippet hizo su trabajo: nació aislado (LEY DE ORO), se validó en caliente sobre un castillo
// real y el 2026-08-30, con el visto bueno del dueño («*funciona ok, aplicar el parche a app.js*»),
// BAJÓ AL MOTOR. Vive en `web/app.js`, en el bloque `mcPasteEsc*` (ver `SYMBOLS.md`), y su guardián
// es `tests/test_pegar_escala.js`, que extrae esas funciones verbatim de `app.js`.
//
// Se deja aquí vacío A PROPÓSITO en vez de borrarlo: si volviera a envolver el motor habría DOS copias
// vivas de la misma lógica —la de aquí, congelada— y ganaría la vieja sin que nadie se enterase.
(function () {
  const enMotor = typeof window.mcPasteEscMeta === 'function' &&
                  typeof window.mcPasteEscGrosores === 'function';
  const aviso = enMotor
    ? '[pegarEscala] ya está en el motor (app.js, bloque mcPasteEsc*). Este snippet no hace nada.'
    : '[pegarEscala] ESTE SNIPPET ESTÁ VACÍO y el motor NO trae el escalado nuevo: app.js es anterior ' +
      'al 2026-08-30. Mira herramientas/parche_app_pegar_escala.py y tests/test_pegar_escala.js.';
  console.log(aviso);
  window.game = window.game || {};
  game.pegarEscala = {
    VERSION: 'graduado-2026-08-30',
    enMotor: enMotor,
    on() { console.log(aviso); return enMotor; },
    off() { console.log(aviso); return enMotor; },
    // Los mandos siguen valiendo: ahora escriben el mismo estado que lee el motor.
    rejilla(n) {
      if (n !== undefined) mc._pegEscRejilla = Math.max(1, n | 0);
      return typeof mcPasteEscRejilla === 'function' ? mcPasteEscRejilla() : mc._pegEscRejilla;
    },
    relleno(f) {
      if (f !== undefined) mc._pegEscRelleno = Math.min(1, Math.max(0.01, +f || 0.5));
      return typeof mcPasteEscRelleno === 'function' ? mcPasteEscRelleno() : mc._pegEscRelleno;
    },
    estado() {
      const r = mc._pegEsc, vivo = !!(r && clipboard && r.ref === clipboard.cells);
      return {
        enMotor: enMotor,
        rejilla: this.rejilla(),
        relleno: this.relleno(),
        nivel: vivo ? r.nivel : null,
        original: vivo ? r.dims : null,
        ahora: typeof mcClipboardDims === 'function' ? mcClipboardDims() : null,
        ejes: vivo && r.planos ? [r.planos[0] - (r.dims.w - 1), r.planos[1] - (r.dims.h - 1),
                                  r.planos[2] - (r.dims.d - 1)] : null
      };
    }
  };
})();
